"""Opt-in GPU copy-back CPU scan and idle snapshot budget experiments."""
import argparse
from pathlib import Path

PATH = Path("crates/victory-gpu/src/shadow.rs")
REPLACEMENTS = (
    ("fn merge_piece(now: &[u8], held: &mut [u8], title: &mut [u8]) -> bool {\n    let mut differs = 0u8;",
     "fn merge_piece(now: &[u8], held: &mut [u8], title: &mut [u8]) -> bool {\n    if sparse_merge_on() {\n        return merge_sparse(now, held, title);\n    }\n    merge_dense(now, held, title)\n}\n\nfn sparse_merge_on() -> bool {\n    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();\n    *ON.get_or_init(|| std::env::var_os(\"VICTORY_BACK_SPARSE_MERGE\").is_some_and(|v| v == \"1\"))\n}\n\n// Compare completed CPU-visible snapshots, not inferred shader dirtiness.\n// Exact equality skips a merge without touching the held or title bytes.\nfn merge_sparse(now: &[u8], held: &mut [u8], title: &mut [u8]) -> bool {\n    let n = now.len().min(held.len()).min(title.len());\n    let mut changed = false;\n    for at in (0..n).step_by(256) {\n        let end = (at + 256).min(n);\n        if now[at..end] != held[at..end] {\n            changed |= merge_dense(&now[at..end], &mut held[at..end], &mut title[at..end]);\n        }\n    }\n    changed\n}\n\nfn merge_dense(now: &[u8], held: &mut [u8], title: &mut [u8]) -> bool {\n    let mut differs = 0u8;"),
    ("fn first_difference(a: &[u8], b: &[u8]) -> Option<usize> {\n    let len = a.len().min(b.len());",
     "fn first_difference(a: &[u8], b: &[u8]) -> Option<usize> {\n    #[cfg(target_arch = \"x86_64\")]\n    if avx_diff_on() {\n        // SAFETY: feature detection in avx_diff_on.\n        return unsafe { avx_difference(a, b, false) };\n    }\n    first_difference_scalar(a, b)\n}\n\n#[cfg(target_arch = \"x86_64\")]\nfn avx_diff_on() -> bool {\n    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();\n    *ON.get_or_init(|| std::env::var_os(\"VICTORY_BACK_AVX2\").is_some_and(|v| v == \"1\")\n        && std::is_x86_feature_detected!(\"avx2\"))\n}\n\n// Read only the common slice length, with unaligned loads and exact\n// byte masks. Reverse scans use the same masks in the opposite order.\n#[cfg(target_arch = \"x86_64\")]\n#[target_feature(enable = \"avx2\")]\nunsafe fn avx_difference(a: &[u8], b: &[u8], reverse: bool) -> Option<usize> {\n    use core::arch::x86_64::{__m256i, _mm256_loadu_si256, _mm256_cmpeq_epi8, _mm256_movemask_epi8};\n    let n = a.len().min(b.len());\n    let full = n / 32;\n    let tail = full * 32;\n    let diff = |at: usize| -> u32 {\n        // SAFETY: callers only pass complete 32-byte chunks; AVX2 checked.\n        unsafe {\n            let x = _mm256_loadu_si256(a.as_ptr().add(at).cast::<__m256i>());\n            let y = _mm256_loadu_si256(b.as_ptr().add(at).cast::<__m256i>());\n            !(_mm256_movemask_epi8(_mm256_cmpeq_epi8(x, y)) as u32)\n        }\n    };\n    if reverse {\n        if let Some(i) = a[tail..n].iter().zip(&b[tail..n]).rposition(|(x, y)| x != y) {\n            return Some(tail + i);\n        }\n        for k in (0..full).rev() {\n            let d = diff(k * 32);\n            if d != 0 { return Some(k * 32 + (31 - d.leading_zeros()) as usize); }\n        }\n    } else {\n        for k in 0..full {\n            let d = diff(k * 32);\n            if d != 0 { return Some(k * 32 + d.trailing_zeros() as usize); }\n        }\n        return a[tail..n].iter().zip(&b[tail..n]).position(|(x, y)| x != y).map(|i| tail + i);\n    }\n    None\n}\n\nfn first_difference_scalar(a: &[u8], b: &[u8]) -> Option<usize> {\n    let len = a.len().min(b.len());"),
    ("fn last_difference(a: &[u8], b: &[u8]) -> Option<usize> {\n    let len = a.len().min(b.len());",
     "fn last_difference(a: &[u8], b: &[u8]) -> Option<usize> {\n    #[cfg(target_arch = \"x86_64\")]\n    if avx_diff_on() {\n        // SAFETY: feature detection in avx_diff_on.\n        return unsafe { avx_difference(a, b, true) };\n    }\n    last_difference_scalar(a, b)\n}\n\nfn last_difference_scalar(a: &[u8], b: &[u8]) -> Option<usize> {\n    let len = a.len().min(b.len());"),
    ("    const KEPT: usize = 512 << 20;\n    let mut pool = POOL.lock().unwrap_or_else(|e| e.into_inner());",
     "    const KEPT: usize = 512 << 20;\n    // Optional hard idle-only budget; no active snapshots are evicted.\n    static CAP: std::sync::OnceLock<Option<usize>> = std::sync::OnceLock::new();\n    let cap = *CAP.get_or_init(|| std::env::var(\"VICTORY_BACK_IDLE_MB\").ok()\n        .and_then(|s| s.parse::<usize>().ok()).and_then(|mb| mb.checked_mul(1 << 20)));\n    if let Some(cap) = cap {\n        let discarded = {\n            let mut pool = POOL.lock().unwrap_or_else(|e| e.into_inner());\n            pool.push(v);\n            trim_idle_pool(&mut pool, cap)\n        };\n        // Large allocations may be expensive to release; not under lock.\n        drop(discarded);\n        return;\n    }\n    let mut pool = POOL.lock().unwrap_or_else(|e| e.into_inner());"),
    ("const NOT_WATCHED: u8 = 2;",
     "// Prefer large reusable buffers that fit, but never exceed the configured\n// capacity budget. Return evicted allocations to the caller for disposal.\nfn trim_idle_pool(pool: &mut Vec<Vec<u8>>, cap: usize) -> Vec<Vec<u8>> {\n    pool.sort_by_key(|v| std::cmp::Reverse(v.capacity()));\n    let mut used = 0usize;\n    let mut keep = Vec::new();\n    let mut discard = Vec::new();\n    for v in pool.drain(..) {\n        if keep.len() < 8 && v.capacity() <= cap.saturating_sub(used) && cap != 0 {\n            used += v.capacity();\n            keep.push(v);\n        } else {\n            discard.push(v);\n        }\n    }\n    *pool = keep;\n    discard\n}\n\n#[cfg(test)]\nmod perf4_tests {\n    use super::*;\n\n    #[test]\n    fn sparse_merge_matches_dense_for_conflicts_and_tails() {\n        for n in [0, 1, 31, 255, 256, 257, 511, 4097] {\n            let old: Vec<u8> = (0..n).map(|i| (i * 13) as u8).collect();\n            for stride in [1, 17, 257, 8192] {\n                let mut gpu = old.clone();\n                let mut cpu = old.clone();\n                for i in (0..n).step_by(stride) { gpu[i] ^= 0x55; }\n                for i in (0..n).step_by(11) { cpu[i] ^= 0x33; }\n                let (mut h1, mut h2) = (old.clone(), old.clone());\n                let (mut t1, mut t2) = (cpu.clone(), cpu);\n                assert_eq!(merge_dense(&gpu, &mut h1, &mut t1), merge_sparse(&gpu, &mut h2, &mut t2));\n                assert_eq!((h1, t1), (h2, t2));\n            }\n        }\n    }\n\n    #[test]\n    fn idle_pool_hard_cap() {\n        let mut pool = vec![Vec::with_capacity(64), Vec::with_capacity(32), Vec::with_capacity(16)];\n        let actual = pool.iter().map(Vec::capacity).sum::<usize>();\n        let discarded = trim_idle_pool(&mut pool, 48);\n        assert!(pool.iter().map(Vec::capacity).sum::<usize>() <= 48);\n        assert_eq!(pool.iter().chain(&discarded).map(Vec::capacity).sum::<usize>(), actual);\n        let _ = trim_idle_pool(&mut pool, 0);\n        assert!(pool.is_empty());\n    }\n\n    #[cfg(target_arch = \"x86_64\")]\n    #[test]\n    fn avx2_matches_scalar_unaligned_and_partial() {\n        if !std::is_x86_feature_detected!(\"avx2\") { return; }\n        for n in [0, 1, 31, 32, 33, 63, 64, 65, 255, 257] {\n            let base = vec![7u8; n + 3];\n            for i in 0..=n {\n                let mut other = base.clone();\n                if i < n { other[i + 1] ^= 0x80; }\n                let a = &base[1..1+n];\n                let b = &other[1..2+n];\n                // SAFETY: checked feature above.\n                unsafe {\n                    assert_eq!(avx_difference(a, b, false), first_difference_scalar(a, b));\n                    assert_eq!(avx_difference(a, b, true), last_difference_scalar(a, b));\n                }\n            }\n        }\n    }\n}\n\nconst NOT_WATCHED: u8 = 2;"),
    ("    let mut i = 0;\n    while i < n {\n        while i < n && mask[i] == 0 {\n            i += 1;\n        }\n        let start = i;\n        while i < n && mask[i] != 0 {\n            i += 1;\n        }\n        if i > start {\n            runs.push((start, i - start));\n        }\n    }\n    Some((first, n))",
     "    let mut i = 0;\n    while i < n {\n        // Skip exact all-zero blocks in the already computed write mask.\n        // Keep the scalar run boundaries and write semantics unchanged.\n        if sparse_merge_on() {\n            while n - i >= 32 && mask[i..i + 32] == [0u8; 32] {\n                i += 32;\n            }\n        }\n        while i < n && mask[i] == 0 {\n            i += 1;\n        }\n        let start = i;\n        while i < n && mask[i] != 0 {\n            i += 1;\n        }\n        if i > start {\n            runs.push((start, i - start));\n        }\n    }\n    Some((first, n))"),
)

def transform(source):
    for old, new in REPLACEMENTS:
        if source.count(old) != 1:
            raise ValueError("Expected exactly one pinned source anchor: " + old[:80])
        source = source.replace(old, new, 1)
    return source

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("checkout", type=Path)
    args = parser.parse_args()
    path = args.checkout / PATH
    try:
        path.write_text(transform(path.read_text(encoding="utf-8")), encoding="utf-8")
    except (OSError, ValueError) as exc:
        parser.exit(1, f"GPU copy preparation failed: {exc}\n")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
